lse if (k<=17) { answer=11; } else if (k<=20) { answer=12; } } } else {// \xe5\xb9\x853\xe3\x81\xae\xe5\xa0\xb4\xe5\x90\x88 if (k==9) { answer=7; } if (k<=11) { answer=8; } else if (k<=12) { answer=9; } else if (k<=14) { answer=10; } else if (k<=15) { answer=11; } else if (k<=17) { answer=12; } else if (k<=18) { answer=13; } else if (k<=20) { answer=14; } } } } // \xef\xbc\xbc(\xe3\x83\xbb\xcf\x89\xe3\x83\xbb\xef\xbc\xbc)\xe3\x80\x80\xe3\x80\x80(\xef\xbc\x8f\xe3\x83\xbb\xcf\x89\xe3\x83\xbb)\xef\xbc\x8f p.WriteAnswerFullLine(answer.ToString()); // // \xef\xbc\xbc(\xe3\x83\xbb\xcf\x89\xe3\x83\xbb\xef\xbc\xbc)\xe3\x80\x80\xe3\x80\x80(\xef\xbc\x8f\xe3\x83\xbb\xcf\x89\xe3\x83\xbb)\xef\xbc\x8f // p.WriteAnswerFullLine(answer); if (i%10==0) Console.WriteLine("{0}\ ->{1}", i, sw.Elapsed); } } private class Train { public char Head { get; set; } public char Tail { get; set; } public HashSet<char> cart; public bool isSingle = false; public Train(string s) { cart=new HashSet<char>(); Head=s[0]; Tail=s[s.Length-1]; foreach (var c in s) { if (! cart.Contains(c))cart.Add(c); } if (cart.Count == 1) { isSingle=true; } } } private static Int64 gcd(Int64 a,Int64 b){ if (a>b) { var c = a; a=b; b=c; } if (b%a == 0) { return a; } else { return gcd(a, b%a); } } } } '